theorem orderedInsertM_cons (a b : α) (l : List α) :
orderedInsertM r a (b :: l) = do
if ← r a b then return a :: b :: l else return b :: (← orderedInsertM r a l)

theorem _root_.Cslib.IsMonadHom.map_orderedInsertM {f : {β : Type} → m β → n β}
    (hf : IsMonadHom m n f) (r : α → α → m Bool) (a : α) (xs : List α) :
    f (orderedInsertM r a xs) = orderedInsertM (fun x y => f (r x y)) a xs

theorem _root_.Cslib.IsMonadHom.map_listInsertionSortM {f : {β : Type} → m β → n β}
    (hf : IsMonadHom m n f) (r : α → α → m Bool) (xs : List α) :
    f (insertionSortM r xs) = insertionSortM (fun x y => f (r x y)) xs

theorem cons_mergeM_cons (x y : α) (xs ys : List α) (le : α → α → m Bool) :
mergeM (x :: xs) (y :: ys) le = do
if ← le x y then
return x :: (← mergeM xs (y :: ys) le)
else
return y :: (← mergeM (x :: xs) ys le)

theorem _root_.Cslib.IsMonadHom.map_listMergeM {f : {β : Type} → m β → n β}
    (hf : IsMonadHom m n f) (xs ys : List α) (le : α → α → m Bool) :
    f (mergeM xs ys le) = mergeM xs ys (fun x y => f (le x y))

theorem _root_.Cslib.IsMonadHom.map_listMergeSortM {f : {β : Type} → m β → n β}
    (hf : IsMonadHom m n f) (xs : List α) (le : α → α → m Bool) :
    f (mergeSortM xs le) = mergeSortM xs (fun x y => f (le x y))

theorem toSingleStartAccept_tr_inl_false {μ : Option Symbol} {y : Bool ⊕ State}
    (h : a.toSingleStartAccept.Tr (.inl false) μ y) :
    μ = none ∧ ∃ s, y = .inr s ∧ s ∈ a.start

theorem toSingleStartAccept_mTr_inr_inl_true {s : State} {μs : List (Option Symbol)}
    (h : a.toSingleStartAccept.MTr (.inr s) μs (.inl true)) :
    ∃ t ∈ a.accept, ∃ μs', μs = μs' ++ [none] ∧ a.MTr s μs' t

theorem reindex_run_iff {f : State ≃ State'} {nba : Buchi State Symbol}
    {xs : ωSequence Symbol} {ss' : ωSequence State'} :
    (nba.reindex f).Run xs ss' ↔ nba.Run xs (ss'.map f.symm)

theorem reindex_run_iff' {f : State ≃ State'} {nba : Buchi State Symbol}
    {xs : ωSequence Symbol} {ss : ωSequence State} :
    (nba.reindex f).Run xs (ss.map f) ↔ nba.Run xs ss

lemma inter_freq_acc_freq_acc {xs : ωSequence Symbol} {ss : ωSequence ((Π i, State i) × Bool)}
    {i : Bool} (h_run : (interNA na acc).Run xs ss) (h_inf : ∃ᶠ k in atTop, ss k ∈ interAcc i acc) :
    ∃ᶠ k in atTop, ss k ∈ interAcc (!i) acc

lemma concat_run_left {xs : ωSequence Symbol} {ss : ωSequence (State1 ⊕ State2)}
    (hc : (concat na1 na2).Run xs ss) (n : ℕ) (hl : ∀ k ≤ n, (ss k).isLeft) :
    ∃ s1 t1, na1.MTr s1 (xs.take n) t1 ∧ s1 ∈ na1.start ∧ ss 0 = inl s1 ∧ ss n = inl t1

lemma concat_run_left_right {xs : ωSequence Symbol} {ss : ωSequence (State1 ⊕ State2)}
    (hc : (concat na1 na2).Run xs ss) (n : ℕ) (hn : 0 < n)
    (hl : ∀ k < n, (ss k).isLeft) (hr : (ss n).isRight) : (xs.take n) ∈ language na1

lemma concat_run_right {xs : ωSequence Symbol} {ss : ωSequence (State1 ⊕ State2)}
    (hc : (concat na1 na2).Run xs ss) (n : ℕ) (hl : ∀ k < n, (ss k).isLeft) (hr : (ss n).isRight) :
    ∃ ss2, na2.Run (xs.drop n) ss2 ∧ ss.drop n = ss2.map inr

theorem concat_run_exists {xs1 : List Symbol} {xs2 : ωSequence Symbol} {ss2 : ωSequence State2}
    (h1 : xs1 ∈ language na1) (h2 : na2.Run xs2 ss2) :
    ∃ ss, (concat na1 na2).Run (xs1 ++ω xs2) ss ∧ ss.drop xs1.length = ss2.map inr

lemma loop_run_left_right {xs : ωSequence Symbol} {ss : ωSequence (Unit ⊕ State)}
    (h : na.loop.Run xs ss) (n : ℕ) (h1 : 0 < n) (h2 : ∀ k, 0 < k → k ≤ n → (ss k).isRight) :
    ∃ s t, na.MTr s (xs.take n) t ∧ s ∈ na.start ∧ ss n = inr t

lemma loop_run_left_right_left {xs : ωSequence Symbol} {ss : ωSequence (Unit ⊕ State)}
    (h : na.loop.Run xs ss) (n : ℕ) (h1 : 0 < n ∧ (ss n).isLeft)
    (h2 : ∀ k, 0 < k → k < n → (ss k).isRight) : xs.take n ∈ language na

lemma loop_run_from_left {xs : ωSequence Symbol} {ss : ωSequence (Unit ⊕ State)}
    (h : na.loop.Run xs ss) (n : ℕ) (h1 : (ss n).isLeft) :
    na.loop.Run (xs.drop n) (ss.drop n)

theorem loop_run_one_iter {xs : ωSequence Symbol} {ss : ωSequence (Unit ⊕ State)} {k : ℕ}
    (h : na.loop.Run xs ss) (h1 : 0 < k) (h2 : (ss k).isLeft) :
    ∃ n, n ≤ k ∧ xs.take n ∈ language na - 1 ∧ na.loop.Run (xs.drop n) (ss.drop n)

theorem loop_run_exists [Inhabited Symbol] {xls : ωSequence (List Symbol)}
    (h : ∀ k, (xls k) ∈ language na - 1) :
    ∃ ss, na.loop.Run xls.flatten ss ∧ ∀ k, ss (xls.cumLen k) = inl ()

theorem LTS.mem_pairViaLang {lts : LTS State Symbol} {via : Set State}
    {s t : State} {xs : List Symbol} : xs ∈ lts.pairViaLang via s t ↔
      ∃ r ∈ via, ∃ xs1 xs2, lts.MTr s xs1 r ∧ lts.MTr r xs2 t ∧ xs1 ++ xs2 = xs

theorem LTS.pairLang_append {lts : LTS State Symbol} {s0 s1 s2 : State} {xs1 xs2 : List Symbol}
    (h1 : xs1 ∈ lts.pairLang s0 s1) (h2 : xs2 ∈ lts.pairLang s1 s2) :
    xs1 ++ xs2 ∈ lts.pairLang s0 s2

theorem LTS.pairLang_split {lts : LTS State Symbol} {s0 s2 : State} {xs1 xs2 : List Symbol}
    (h : xs1 ++ xs2 ∈ lts.pairLang s0 s2) :
    ∃ s1, xs1 ∈ lts.pairLang s0 s1 ∧ xs2 ∈ lts.pairLang s1 s2

theorem LTS.pairViaLang_append_pairLang {lts : LTS State Symbol}
    {s0 s1 s2 : State} {xs1 xs2 : List Symbol} {via : Set State}
    (h1 : xs1 ∈ lts.pairViaLang via s0 s1) (h2 : xs2 ∈ lts.pairLang s1 s2) :
    xs1 ++ xs2 ∈ lts.pairViaLang via s0 s2

theorem LTS.pairLang_append_pairViaLang {lts : LTS State Symbol}
    {s0 s1 s2 : State} {xs1 xs2 : List Symbol} {via : Set State}
    (h1 : xs1 ∈ lts.pairLang s0 s1) (h2 : xs2 ∈ lts.pairViaLang via s1 s2) :
    xs1 ++ xs2 ∈ lts.pairViaLang via s0 s2

theorem iProd_run_iff {na : (i : I) → NA (State i) Symbol}
    {xs : ωSequence Symbol} {ss : ωSequence (Π i, State i)} :
    (iProd na).Run xs ss ↔ ∀ i, (na i).Run xs (ss.map (· i))

theorem iSum_run_iff {na : (i : I) → NA (State i) Symbol}
    {xs : ωSequence Symbol} {ss : ωSequence (Σ i, State i)} :
    (iSum na).Run xs ss ↔ ∃ i ss_i, (na i).Run xs ss_i ∧ ss_i.map (Sigma.mk i) = ss

theorem totalize_run_mtr {xs : ωSequence Symbol} {ss : ωSequence (Option State)} {n : ℕ}
    (h : na.totalize.Run xs ss) (hl : (ss n).isSome) :
    ∃ s t, na.MTr s (xs.take n) t ∧ s ∈ na.start ∧ ss 0 = some s ∧ ss n = some t

theorem totalize_mtr_run [Inhabited Symbol] {xl : List Symbol} {s t : State}
    (hs : s ∈ na.start) (hm : na.MTr s xl t) :
    ∃ xs ss, na.totalize.Run (xl ++ω xs) ss ∧ ss 0 = some s ∧ ss xl.length = some t

def TwoWayNA.toCfgNA {State Symbol : Type*} (a : TwoWayNA State Symbol)
    (input : List Symbol) :
    NA.FinAcc (TwoWayNACfg State Symbol) (Symbol × SignType)

theorem TwoWayNACfg.eta {input : List Symbol} {c : TwoWayNACfg State Symbol}
    (h : c.input = input) (h' : (c.pos : ℕ) < input.length + 1) :
    ({ input := input, pos := ⟨c.pos, h'⟩, state := c.state } : TwoWayNACfg State Symbol) = c

theorem TwoWayNA.getElem_of_tr {a : TwoWayNA State Symbol} {input : List Symbol}
    {c c' : TwoWayNACfg State Symbol} {x : Symbol} {m : SignType}
    (htr : (a.toCfgNA input).Tr c (x, m) c') (hc : c.input = input) :
    ∃ h : (c.pos : ℕ) < input.length, input[(c.pos : ℕ)] = x

theorem mTr_take_of_mTr_toCfgNA {c c' : TwoWayNACfg State Symbol}
    {μs : List (Symbol × SignType)}
    (hstart : c ∈ (a.toTwoWayNA.toCfgNA input).start)
    (hrun : (a.toTwoWayNA.toCfgNA input).MTr c μs c') :
    a.MTr c.state (input.take c'.pos) c'.state

theorem Circuit.mapInputs_mapInputs {inputCount' inputCount'' : ℕ}
    (g : Fin inputCount' → Fin inputCount'') (f : Fin inputCount → Fin inputCount')
    (c : Circuit σ inputCount outputCount) : (c.mapInputs f).mapInputs g = c.mapInputs (g ∘ f)

def Circuit.Computes (c : Circuit σ inputCount outputCount)
    (interpretation : Interpretation σ U) (f : (Fin inputCount → U) → Fin outputCount → U) :
    Prop

def Circuit.ComputesOn (c : Circuit σ inputCount outputCount)
    (interpretation : Interpretation σ U) (S : Set (Fin inputCount → U))
    (f : (Fin inputCount → U) → Fin outputCount → U) : Prop

theorem Circuit.Computes.computesOn {c : Circuit σ inputCount outputCount}
    {interpretation : Interpretation σ U} {f : (Fin inputCount → U) → Fin outputCount → U}
    (h : c.Computes interpretation f) (S : Set (Fin inputCount → U)) :
    c.ComputesOn interpretation S f

theorem synthesis_minterm {k : ℕ} (wires : Fin k → Fin n) (value : Fin k → Bool) :
    Synthesis interpretation (inputs n) {fun x => decide ((fun i => x (wires i)) = value)}
      (2 * k + 1)

theorem Computes.comp {c : Circuit σ n m} {d : Circuit σ m p}
    {f : (Fin n → U) → Fin m → U} {g : (Fin m → U) → Fin p → U}
    (hc : c.Computes I f) (hd : d.Computes I g) : (d.comp c).Computes I (g ∘ f)

theorem Computes.append {c : Circuit σ n m} {d : Circuit σ n p}
    {f : (Fin n → U) → Fin m → U} {g : (Fin n → U) → Fin p → U}
    (hc : c.Computes I f) (hd : d.Computes I g) :
    (c.append d).Computes I (fun x => Fin.append (f x) (g x))

theorem ComputesOn.comp {c : Circuit σ n m} {d : Circuit σ m p} {S : Set (Fin n → U)}
    {f : (Fin n → U) → Fin m → U} {g : (Fin m → U) → Fin p → U}
    (hc : c.ComputesOn I S f) (hd : d.ComputesOn I (f '' S) g) :
    (d.comp c).ComputesOn I S (g ∘ f)

theorem ComputesOn.append {c : Circuit σ n m} {d : Circuit σ n p} {S : Set (Fin n → U)}
    {f : (Fin n → U) → Fin m → U} {g : (Fin n → U) → Fin p → U}
    (hc : c.ComputesOn I S f) (hd : d.ComputesOn I S g) :
    (c.append d).ComputesOn I S (fun x => Fin.append (f x) (g x))

theorem ext
{source : Interpretation σ U₁}
{target : Interpretation σ U₂}
{left right : Homomorphism source target}
(map_eq : left.map = right.map) : left = right

def comp
    {i₁ : Interpretation σ U₁}
    {i₂ : Interpretation σ U₂}
    {i₃ : Interpretation σ U₃}
    (outer : Homomorphism i₂ i₃)
    (inner : Homomorphism i₁ i₂) : Homomorphism i₁ i₃

theorem comp_map
{i₁ : Interpretation σ U₁}
{i₂ : Interpretation σ U₂}
{i₃ : Interpretation σ U₃}
(outer : Homomorphism i₂ i₃)
(inner : Homomorphism i₁ i₂) :
(outer.comp inner).map = outer.map ∘ inner.map

theorem id_comp
{source : Interpretation σ U₁}
{target : Interpretation σ U₂}
(homomorphism : Homomorphism source target) :
(Homomorphism.id target).comp homomorphism = homomorphism

theorem comp_id
{source : Interpretation σ U₁}
{target : Interpretation σ U₂}
(homomorphism : Homomorphism source target) :
homomorphism.comp (Homomorphism.id source) = homomorphism

theorem comp_assoc
    {i₁ : Interpretation σ U₁}
    {i₂ : Interpretation σ U₂}
    {i₃ : Interpretation σ U₃}
    {i₄ : Interpretation σ U₄}
    (outer : Homomorphism i₃ i₄)
    (middle : Homomorphism i₂ i₃)
    (inner : Homomorphism i₁ i₂) :
    (outer.comp middle).comp inner = outer.comp (middle.comp inner)

theorem Line.mapInputs_mapInputs {inputCount' inputCount'' : ℕ}
    (g : Fin inputCount' → Fin inputCount'') (f : Fin inputCount → Fin inputCount')
    (l : Line σ inputCount gateCount) : (l.mapInputs f).mapInputs g = l.mapInputs (g ∘ f)

def Program.gateEquiv (σ : Signature) (inputCount gateCount : Nat) :
    Program σ inputCount (gateCount + 1) ≃
      Program σ inputCount gateCount × Line σ inputCount gateCount

theorem Program.foldl_rel (p : Program σ inputCount gateCount) (R : α → β → Prop)
    {f : ∀ {k : Nat}, α → Line σ inputCount k → α}
    {f' : ∀ {k : Nat}, β → Line σ inputCount k → β}
    {a : α} {b : β} (hinit : R a b)
    (hstep : ∀ {k : Nat} {a : α} {b : β} (line : Line σ inputCount k),
      R a b → R (f a line) (f' b line)) : R (p.foldl f a) (p.foldl f' b)

theorem Program.foldr_rel (p : Program σ inputCount gateCount) (R : α → β → Prop)
    {f : ∀ {k : Nat}, Line σ inputCount k → α → α}
    {f' : ∀ {k : Nat}, Line σ inputCount k → β → β}
    {a : α} {b : β} (hinit : R a b)
    (hstep : ∀ {k : Nat} {a : α} {b : β} (line : Line σ inputCount k),
      R a b → R (f line a) (f' line b)) : R (p.foldr f a) (p.foldr f' b)

theorem Program.mapInputs_mapInputs {inputCount' inputCount'' : ℕ}
    (g : Fin inputCount' → Fin inputCount'') (f : Fin inputCount → Fin inputCount')
    (p : Program σ inputCount gateCount) : (p.mapInputs f).mapInputs g = p.mapInputs (g ∘ f)

instance Program.instDecidableFanInAtMost {gateCount : Nat}
