theorem Line.mem_inputSupport
{line : Line σ inputCount gateCount}
{wireSupport : Wire inputCount gateCount → Finset (Fin inputCount)}
{input : Fin inputCount} :
input ∈ line.inputSupport wireSupport ↔
∃ argument, input ∈ wireSupport (line.wires argument)

theorem Circuit.exists_simulation_le (c : Circuit σ n m) {b : ℕ}
    (h : J.SimulatesWithCost I (fun _ => b)) :
    ∃ d : Circuit τ n m, d.eval J = c.eval I ∧ d.size ≤ b * c.size

theorem Interpretation.SimulatesWithCost.trans {b c : ℕ}
    (hK : K.SimulatesWithCost J (fun _ => b)) (hJ : J.SimulatesWithCost I (fun _ => c)) :
    K.SimulatesWithCost I (fun _ => b * c)

theorem Circuit.ComputesOn.simulation {c : Circuit σ n m} {S : Set (Fin n → U)}
    {f : (Fin n → U) → Fin m → U} (hc : c.ComputesOn I S f) (h : J.Simulates I) :
    ∃ d : Circuit τ n m, d.ComputesOn J S f

theorem Circuit.Computes.simulation {c : Circuit σ n m} {f : (Fin n → U) → Fin m → U}
    (hc : c.Computes I f) (h : J.Simulates I) :
    ∃ d : Circuit τ n m, d.Computes J f

theorem binary (hf : Synthesis I s {f} a) (hg : Synthesis I s {g} b) (op : σ.Op) :
    Synthesis I s {fun x => I op (fun i => if i.val = 0 then f x else g x)}
      (a + b + 1)

theorem combine {result : (Fin n → U) → U} {c : ℕ}
    (hf : Synthesis I s {f} a) (hg : Synthesis I s {g} b)
    (h : Synthesis I {f, g} {result} c) : Synthesis I s {result} (a + b + c)

theorem exists_circuit_outputs {m cost : ℕ} {f : Fin m → (Fin n → U) → U}
    (h : Synthesis I (inputs n) (Set.range f) cost) :
    ∃ c : Circuit σ n m, c.Computes I (fun x j => f j x) ∧ c.size ≤ cost

theorem stepL {ps : Set P} {x : Action P M} {s1 s2 s3 : State P M S}
