theorem diamond {ps : Set P} {s s1 s2 : State P M S}
    (h1 : a.CanReachVia ps s s1) (h2 : a.CanReachVia psᶜ s s2) :
    ∃ s', a.CanReachVia psᶜ s1 s' ∧ a.CanReachVia ps s2 s'

theorem subset_inp [Fintype P] {ps : Set P} {inp1 inp2 : P → Bool} {s1 : State P M S}
    (he : EqOn inp1 inp2 ps) (hr : a.CanReachVia ps (a.start inp1) s1) :
    ∃ s2, a.CanReachVia ps (a.start inp2) s2 ∧ s2.proc = s1.proc

theorem not_procFaulty_of_numProcFaulty [Fintype P]
    {ss : ωSequence (State P M S)} {xs : ωSequence (Action P M)}
    (h : numProcFaulty ss xs < card P) : ∃ p, ¬ ProcFaulty p ss xs

theorem numProcFaulty_le_not_procFair [Fintype P]
    {ss : ωSequence (State P M S)} {xs : ωSequence (Action P M)} {ps : Set P}
    (h : ∀ p, p ∈ ps → ProcFair p ss xs) : numProcFaulty ss xs ≤ card P - ps.ncard

theorem AdmissibleRun.fault_mono [Fintype P] {f f' : ℕ}
    {xs : ωSequence (Action P M)} {ss : ωSequence (State P M S)}
    (hle : f ≤ f') (ha : a.AdmissibleRun inp f ss xs) : a.AdmissibleRun inp f' ss xs

theorem foldList_forallActions {r : Action P M → Prop}
    (s : State P M S) (ml : List (Message P M)) (ms : Finset (Message P M))
    (h : d.ForallActions r) : (d.foldList s ml ms).fst.Forall r

theorem fairSeg_forallActions {d : DeliverMsg P M S} {r : Action P M → Prop}
    (ps : Set P) (s0 : State P M S) (k : ℕ) (ha : d.ForallActions r) (hn : r none) :
