theorem omega_forall_actions {d : DeliverMsg P M S} {ps : Set P}
    {q : State P M S → Prop} {r : Action P M → Prop}
    (hd : a.FairDeliverMsg d ps q) (s0 : State P M S) (hs0 : q s0)
