lemma natAbs_le_spaceUsedByTape_of_mem_visited (p : ntm.RunPath input) {i : Fin k} {z : ℤ}
    (hz : z ∈ p.visitedByTapeHead i) :
    (z - p.head.workTapePos i).natAbs ≤ p.spaceUsedByTape i

noncomputable def PolyTimeComputable.comp {f g : List Symbol → List Symbol}
    (hf : PolyTimeComputable f) (hg : PolyTimeComputable g) :
    PolyTimeComputable (g ∘ f)

theorem forces_iff_isCertificate_support {f : BooleanFunction n} {x : BitString n}
    {C : PartialAssignment n} (hC : Agrees C x) :
    Forces f C (f x) ↔ IsCertificate f x (support C)

lemma mem_forcingAssignments {f : BooleanFunction n} {x : BitString n}
    {C : PartialAssignment n} :
    C ∈ forcingAssignments f x ↔ Agrees C x ∧ Forces f C (f x)

theorem sensitiveBlock_inter_nonempty {f : BooleanFunction n} {x : BitString n} {B : Block n}
    (hB : IsSensitiveBlock f x B) {S : Finset (Fin n)} (hS : IsCertificate f x S) :
    (B ∩ S).Nonempty

lemma card_le_card_of_isSensitiveFamily {f : BooleanFunction n} {x : BitString n}
    {F : Finset (Block n)} {S : Finset (Fin n)}
    (hF : IsSensitiveFamily f x F) (hS : IsCertificate f x S) : F.card ≤ S.card

theorem JumpsBoundedBy.mono {instr : Instr} {len1 len2 : ℕ}
    (h : instr.JumpsBoundedBy len1) (hle : len1 ≤ len2) :
    instr.JumpsBoundedBy len2

theorem JumpsBoundedBy.shiftJumps {instr : Instr} {len offset : ℕ}
    (h : instr.JumpsBoundedBy len) :
    (instr.shiftJumps offset).JumpsBoundedBy (offset + len)

theorem eq_of_halts {init s₁ s₂ : State}
    (h1 : Steps p init s₁) (hh1 : s₁.isHalted p)
    (h2 : Steps p init s₂) (hh2 : s₂.isHalted p) : s₁ = s₂

theorem Steps.from_toStandardForm_halts {p : Program} {s s' : State}
    (hsteps : Steps p.toStandardForm s s') (hhalted : s'.isHalted p.toStandardForm) :
    ∃ s₂, Steps p s s₂ ∧ s₂.isHalted p ∧ s'.regs = s₂.regs

theorem Program.IsStraightLine.append {p q : Program}
    (hp : p.IsStraightLine) (hq : q.IsStraightLine) :
    (p ++ q).IsStraightLine

theorem Program.IsStraightLine.cons {instr : Instr} {p : Program}
    (hinstr : ¬instr.IsJump) (hp : p.IsStraightLine) :
