items.doc:
An advantage is negligible when it decays faster than every inverse polynomial in the
security parameter. The nonnegative codomain records that advantages are magnitudes;
the decay condition is Mathlib's superpolynomial decay in the nonnegative reals.

items.statement:
theorem Negligible.polynomiallyBounded_mul {ε : ℕ → ℝ≥0} {p : ℕ → ℕ}
    (hε : Negligible ε) (hp : PolynomiallyBounded p) :
    Negligible (fun n => (p n : ℝ≥0) * ε n)

theorem Secure.of_admissible {G : Family Seed Output}
    {Admissible Restricted : (∀ n, Adversary (Output n)) → Prop}
    (h : G.Secure Admissible)
    (hsub : ∀ adversary_family, Restricted adversary_family → Admissible adversary_family) :
    G.Secure Restricted

theorem SecureWithError.secure {G : Family Seed Output}
    {Admissible : (∀ n, Adversary (Output n)) → Prop} {ε : ℕ → ℝ≥0}
    (h : G.SecureWithError Admissible ε)
    (hε : Asymptotics.SuperpolynomialDecay atTop (fun n : ℕ => (n : ℝ))
      (fun n => (ε n : ℝ))) : G.Secure Admissible

theorem not_secure_of_bitstring_stretch {seedLength outputLength : ℕ → ℕ}
    (G : Family (fun n => Fin (seedLength n) → Bool) (fun n => Fin (outputLength n) → Bool))
    {Admissible : (∀ n, Adversary (Fin (outputLength n) → Bool)) → Prop}
    (ha : Admissible (fun n => (G n).rangeAdversary))
    (hstretch : ∀ᶠ n in atTop, seedLength n < outputLength n) :
    ¬ G.Secure Admissible

theorem not_secure_of_bitVec_stretch {seedLength outputLength : ℕ → ℕ}
    (G : Family (fun n => BitVec (seedLength n)) (fun n => BitVec (outputLength n)))
    {Admissible : (∀ n, Adversary (BitVec (outputLength n))) → Prop}
    (ha : Admissible (fun n => (G n).rangeAdversary))
    (hstretch : ∀ᶠ n in atTop, seedLength n < outputLength n) :
    ¬ G.Secure Admissible

theorem Secure.of_admissible {G : Generator Seed Output}
    {Admissible Restricted : Adversary Output → Prop} {ε : ℝ≥0}
    (h : G.Secure Admissible ε) (hsub : ∀ adversary, Restricted adversary → Admissible adversary) :
    G.Secure Restricted ε

theorem Secure.prod {G : Generator Seed Output}
    {Admissible₁ : Adversary Output → Prop}
    {Admissible₂ : Adversary (Output × Output) → Prop}
    {ε : ℝ≥0}
    (hG : G.Secure Admissible₁ ε)
    (hLeft : ∀ A, Admissible₂ A → Admissible₁ (G.leftReduction A))
    (hRight : ∀ A, Admissible₂ A → Admissible₁ (rightReduction A)) :
    G.prod.Secure Admissible₂ (2 * ε)

theorem PerfectlyBinding.dist_commitmentDist_eq_one
    [Fintype Commitment] {scheme : Scheme Message Commitment Opening}
    (hbind : scheme.PerfectlyBinding) {message₀ message₁ : Message}
    (hne : message₀ ≠ message₁) :
    dist (scheme.commitmentDist message₀)
      (scheme.commitmentDist message₁) = 1

noncomputable def viewDistOf {Secret Randomness Party Share : Type*}
    (gen : PMF Randomness) (share : Randomness → Secret → Party → Share)
    (s : Finset Party) (secret : Secret) : PMF (s → Share)

theorem natDegree_sharingPolynomial_le (secretValue : F) (tail : _root_.Polynomial F) {n : ℕ}
    (hdeg : tail.degree < n) :
    (sharingPolynomial secretValue tail).natDegree ≤ n

theorem degree_sharingPolynomial_lt_succ (secretValue : F) (tail : _root_.Polynomial F) {n : ℕ}
    (hdeg : tail.degree < n) :
    (sharingPolynomial secretValue tail).degree < (n + 1 : WithBot ℕ)

theorem Interprets.eq {handler : {ι : Type u} → F ι → m ι} {interp : FreeM F α → m α}
    (h : Interprets handler interp) :
    interp = (·.liftM @handler)

theorem liftM_eq_foldFreeM {m : Type u → Type w} [Monad m] {α : Type u}
    (interp : {ι : Type u} → F ι → m ι) :
    FreeM.liftM interp (α := α) = foldFreeM pure (fun op k => interp op >>= k)

theorem mk' [LawfulFunctor m] [LawfulFunctor n] {f : ∀ {α}, m α → n α}
    (map_map : ∀ {α β} (g : α → β) (x : m α), f (g <$> x) = g <$> f x) :
    IsFunctorHom m n f

protected theorem comp {f : ∀ {α}, n α → p α} {g : ∀ {α}, m α → n α}
    (hf : IsFunctorHom n p f) (hg : IsFunctorHom m n g) :
    IsFunctorHom m p (f ∘ g)

protected theorem comp {f : ∀ {α}, n α → p α} {g : ∀ {α}, m α → n α}
    (hf : IsApplicativeHom n p f) (hg : IsApplicativeHom m n g) :
    IsApplicativeHom m p (f ∘ g)

protected theorem comp {f : ∀ {α}, n α → p α} {g : ∀ {α}, m α → n α}
    (hf : IsMonadHom n p f) (hg : IsMonadHom m n g) :
    IsMonadHom m p (f ∘ g)

protected theorem comp {f : ∀ {α}, n α → p α} {g : ∀ {α}, m α → n α}
    (hf : IsAlternativeHom n p f) (hg : IsAlternativeHom m n g) :
    IsAlternativeHom m p (f ∘ g)

protected theorem comp {f : ∀ {α}, n α → p α} {g : ∀ {α}, m α → n α}
    (hf : IsAlternativeMonadHom n p f) (hg : IsAlternativeMonadHom m n g) :
    IsAlternativeMonadHom m p (f ∘ g)

lemma IsChainFromTo.reflTransGen_of_mem' (hc : chain.IsChainFromTo r a b) {x : α}
    (mem : x ∈ chain) :
    Relation.ReflTransGen r x b

theorem flatten_get_add [Inhabited α] (ls : ωSequence (List α)) {n k : ℕ}
    (hk : k < (ls n).length) (hpos : ∀ n, 0 < (ls n).length) :
    ls.flatten (ls.cumLen n + k) = (ls n)[k]

theorem segment_toSegs_cumLen {f : ℕ → ℕ}
    (hm : StrictMono f) (h0 : f 0 = 0) (s : ωSequence α) :
    (s.toSegs f).cumLen = f

theorem strictMono_flatten [Inhabited α] {f : ℕ → ℕ}
    (hm : StrictMono f) (h0 : f 0 = 0) (s : ωSequence α) :
    (s.toSegs f).flatten = s

theorem frequently_in_strictMono {p : ℕ → Prop} {f : ℕ → ℕ}
    (hm : StrictMono f) (hf : ∃ᶠ k in atTop, p k) :
    ∃ᶠ n in atTop, ∃ k, k < f (n + 1) - f n ∧ p (f n + k)

theorem extract_eq_extract {xs xs' : ωSequence α} {m n m' n' : ℕ}
    (h : xs.extract m n = xs'.extract m' n') :
    n - m = n' - m' ∧ ∀ k < n - m, xs (m + k) = xs' (m' + k)

theorem Interprets.eq {handler : (a : P.A) → m (P.B a)} {eval : P.FreeM α → m α}
    (h : Interprets handler eval) :
    eval = (·.liftM handler)

lemma liftM_seq {α β : Type uB}
    (interp : (a : P.A) → m (P.B a)) (x : P.FreeM (α → β)) (y : P.FreeM α) :
    (x <*> y).liftM interp = x.liftM interp <*> y.liftM interp

lemma liftM_seqLeft {α β : Type uB}
    (interp : (a : P.A) → m (P.B a)) (x : P.FreeM α) (y : P.FreeM β) :
    (x <* y).liftM interp = x.liftM interp <* y.liftM interp

lemma liftM_seqRight {α β : Type uB}
    (interp : (a : P.A) → m (P.B a)) (x : P.FreeM α) (y : P.FreeM β) :
    (x *> y).liftM interp = x.liftM interp *> y.liftM interp

theorem liftM_eq_foldFreeM {m : Type uB → Type v} [Monad m] {α : Type uB}
    (interp : (a : P.A) → m (P.B a)) :
    FreeM.liftM interp (α := α) = foldFreeM pure (fun a k => interp a >>= k)

items.doc:
A relation `r` relates two elements of `α` in `n` steps
if there is a chain of `n` pairs `(t_i, t_{i+1})` such that `r t_i t_{i+1}` for each `i`,
starting from the first element and ending at the second.

items.statement:
lemma RelatesInSteps.trans {a b c : α} {n m : ℕ}
    (h₁ : RelatesInSteps r a b n) (h₂ : RelatesInSteps r b c m) :
    RelatesInSteps r a c (n + m)

lemma RelatesInSteps.map {α α' : Type*}
    {r : α → α → Prop} {r' : α' → α' → Prop}
    (g : α → α') (hg : ∀ a b, r a b → r' (g a) (g b))
    {a b : α} {n : ℕ} (h : RelatesInSteps r a b n) :
    RelatesInSteps r' (g a) (g b) n

lemma _root_.List.IsChainFromTo.relatesInSteps {chain : List α} {n : ℕ}
    (hc : chain.IsChainFromTo r a b) (hlen : chain.length = n + 1) :
    RelatesInSteps r a b n

lemma RelatesWithinSteps.trans {a b c : α} {n₁ n₂ : ℕ}
    (h₁ : RelatesWithinSteps r a b n₁) (h₂ : RelatesWithinSteps r b c n₂) :
    RelatesWithinSteps r a c (n₁ + n₂)

theorem Bisimilarity.symm {State₁ State₂ : Type*}
    {lts₁ : LTS State₁ Label} {lts₂ : LTS State₂ Label} {s₁ : State₁} {s₂ : State₂}
    (h : s₁ ~[lts₁,lts₂] s₂) : s₂ ~[lts₂,lts₁] s₁

theorem Bisimilarity.deterministic_traceEq_bisim {lts₁ : LTS State₁ Label} {lts₂ : LTS State₂ Label}
    [lts₁.Deterministic] [lts₂.Deterministic] (h : s₁ ~tr[lts₁,lts₂] s₂) :
    (s₁ ~[lts₁,lts₂] s₂)

theorem Deterministic.bisim_tfae {lts₁ : LTS State₁ Label} {lts₂ : LTS State₂ Label}
    [lts₁.Deterministic] [lts₂.Deterministic] (s₁ : State₁) (s₂ : State₂) :
    [s₁ ~[lts₁,lts₂] s₂, s₁ ~tr[lts₁,lts₂] s₂, s₁ ≤≥[lts₁,lts₂] s₂].TFAE

theorem Bisimilarity.deterministic_bisim_eq_traceEq
    {lts₁ : LTS State₁ Label} {lts₂ : LTS State₂ Label}
    [lts₁.Deterministic] [lts₂.Deterministic] : Bisimilarity lts₁ lts₂ = TraceEq lts₁ lts₂

theorem WeakBisimilarity.trans [HasTau Label]
    {lts₁ : LTS State₁ Label} {lts₂ : LTS State₂ Label} {lts₃ : LTS State₃ Label}
    (h1 : s₁ ≈[lts₁,lts₂] s₂) (h2 : s₂ ≈[lts₂,lts₃] s₃) : s₁ ≈[lts₁,lts₃] s₃

